                activeDispatches.push({
                    key,
                    scene: { bookId, chapterId, sceneId },
                    stage,
                    token: token || null,
                    metadata
                });

                count++;
            }
        }
    } while (cursor !== 0 && count < limit);

    return activeDispatches;
}

