                        ready = (vbookProgress.sceneIndex + 1).coerceIn(0, totalVBook)
                        pctVBook = if (ready >= totalVBook) 100 else (ready * 100 / totalVBook).coerceIn(0, 99)
                        countText = labels.vbookScenesFormat(ready, totalVBook)
