// ======================================================
// Layer Config Service
// ======================================================
// Persists per-book defaults for initial/bulk generation:
//   - audio_enabled:  base layer, always true (audio is the story narration)
//   - image_enabled:  storyboard / IU images
//   - video_enabled:  full video composition (requires image_enabled to be true)
//
// Storage:
//   Redis key: animastor:layer-config:<bookId>
//   Value:     JSON { audio_enabled, image_enabled, video_enabled, updated_at }
//
// Used by:
//   - POST /api/v1/generate                  (multipart, on book import)
//   - POST /api/v1/book/:bookId/regenerate   (in-place regeneration)
//   - GET  /api/v1/book/:bookId/layer-config (read)
//   - PUT  /api/v1/book/:bookId/layer-config (write)
//   - GET  /api/v1/book/:bookId/assets-state (derived: which layers have content)

const SCOPES = Object.freeze({
    CURRENT_SCENE:      'current_scene',
    CURRENT_CHAPTER:    'current_chapter',
    FROM_CURRENT_SCENE: 'from_current_scene',
    WHOLE_BOOK:         'whole_book',
});

const KEY_PREFIX = 'animastor:layer-config:';
const key = (bookId) => `${KEY_PREFIX}${bookId}`;

const DEFAULTS = Object.freeze({
    audio_enabled: true,
    image_enabled: true,
    video_enabled: true,
});

function normalize(raw) {
    if (!raw) return { ...DEFAULTS };
    let obj = raw;
    if (typeof raw === 'string') {
        try { obj = JSON.parse(raw); } catch { obj = {}; }
    }
    return {
        audio_enabled: obj.audio_enabled !== false,
        image_enabled: obj.image_enabled !== false,
        video_enabled: obj.video_enabled !== false,
    };
}

async function get(redis, bookId) {
    if (!redis || !bookId) return { ...DEFAULTS };
    const raw = await redis.get(key(bookId));
    return normalize(raw);
}

async function set(redis, bookId, partial) {
    if (!redis || !bookId) return { ...DEFAULTS };
    const current = await get(redis, bookId);
    const next = {
        audio_enabled: partial.audio_enabled !== undefined ? !!partial.audio_enabled : current.audio_enabled,
        image_enabled: partial.image_enabled !== undefined ? !!partial.image_enabled : current.image_enabled,
        video_enabled: partial.video_enabled !== undefined ? !!partial.video_enabled : current.video_enabled,
    };
    await redis.set(key(bookId), JSON.stringify(next));
    return next;
}

function isValidScope(value) {
    return Object.values(SCOPES).includes(value);
}

module.exports = {
    SCOPES,
    DEFAULTS,
    key,
    get,
    set,
    normalize,
    isValidScope,
};
// Independent generation task registry.
//
// Every user command gets its own task id, worker type, scope, and exact scene
// targets. This is intentionally separate from book-wide layer preferences:
// multiple Audio/Image/Video commands can coexist without overwriting state.

const { randomUUID } = require('crypto');

const KEY_PREFIX = 'animastor:generation-progress';
const TTL_SECONDS = 4 * 60 * 60;
const TERMINAL_RETENTION_MS = 30 * 1000;
const WORKER_TYPES = new Set(['audio', 'image', 'video']);

function key(bookId) {
    return `${KEY_PREFIX}:${bookId}`;
}

function taskId(type) {
    return `generation-${type}-${Date.now()}-${randomUUID().slice(0, 8)}`;
}

function normalizeScope(scope) {
    return {
        scope: scope?.scope || 'whole_book',
        chapter_id: scope?.chapterId || scope?.chapter_id || null,
        scene_id: scope?.sceneId || scope?.scene_id || null,
    };
}

function targetsForType(dirtyScenes, type) {
    const unique = new Map();
    for (const scene of dirtyScenes || []) {
        if (!scene?.chapter_id || !scene?.scene_id) continue;
        if (Array.isArray(scene.dirty_layers) && !scene.dirty_layers.includes(type)) continue;
        const sceneKey = `${scene.chapter_id}:${scene.scene_id}`;
        unique.set(sceneKey, {
            chapter_id: scene.chapter_id,
            scene_id: scene.scene_id,
        });
    }
    return [...unique.values()];
}

async function writeTask(redis, bookId, task) {
    await redis.hset(key(bookId), task.task_id, JSON.stringify(task));
    await redis.expire(key(bookId), TTL_SECONDS);
    return task;
}

async function createTasks(redis, bookId, workerTypes, scope, dirtyScenes) {
    if (!redis || !bookId) return [];

    const selectedScope = normalizeScope(scope);
    const created = [];
    for (const type of [...new Set(workerTypes || [])]) {
        if (!WORKER_TYPES.has(type)) continue;
        const targets = targetsForType(dirtyScenes, type);
        if (targets.length === 0) continue;

        const task = {
            task_id: taskId(type),
            type,
            status: 'active',
            ...selectedScope,
            targets,
            started_at: Date.now(),
            completed_at: null,
            cancelled_at: null,
        };
        await writeTask(redis, bookId, task);
        created.push(task);
    }
    return created;
}

async function listTasks(redis, bookId) {
    if (!redis || !bookId) return [];
    const raw = await redis.hgetall(key(bookId));
    const tasks = [];
    const expiredIds = [];
    const now = Date.now();

    for (const [id, value] of Object.entries(raw || {})) {
        try {
            const task = JSON.parse(value);
            if (!task.task_id) task.task_id = id;
            const terminalAt = task.completed_at || task.cancelled_at;
            if (terminalAt && now - terminalAt >= TERMINAL_RETENTION_MS) {
                expiredIds.push(id);
                continue;
            }
            tasks.push(task);
        } catch (_) {
            expiredIds.push(id);
        }
    }

    for (const id of expiredIds) {
        await redis.hdel(key(bookId), id);
    }

    return tasks.sort((a, b) => (a.started_at || 0) - (b.started_at || 0));
}

async function getTask(redis, bookId, id) {
    if (!redis || !bookId || !id) return null;
    const raw = await redis.hget(key(bookId), id);
    if (!raw) return null;
    try {
        return JSON.parse(raw);
    } catch (_) {
        await redis.hdel(key(bookId), id);
        return null;
    }
}

async function updateTask(redis, bookId, id, updates) {
    const task = await getTask(redis, bookId, id);
    if (!task) return null;
    return writeTask(redis, bookId, { ...task, ...updates, task_id: task.task_id || id });
}

