            dispatched: 0,
            throttled: 0,
            skipped: 0,
            completed: 0,
            errors: []
        };

        const activeBookIds = new Set();
        for (const sceneKey of activeKeys) {
            const parsed = parseSceneKey(sceneKey);
            if (parsed) activeBookIds.add(parsed.bookId);
        }
        for (const bookId of activeBookIds) {
