        }

        log(`=== TICK COMPLETE ===`);
        log(`Active: ${summary.totalActive}, Dispatched: ${summary.dispatched}, Skipped: ${summary.skipped}, Throttled: ${summary.throttled}, Completed: ${summary.completed}`);

        if (summary.errors.length > 0) {
