                warn: message => warnings.push(message),
                fetchImpl: async url => {
                    const dispatchId = new URL(url).searchParams.get('dispatch_id');
                    const response = responses.get(dispatchId);
                    if (response instanceof Error) throw response;
                    return response;
                },
            }
        );

